-- Contribution copy inserted directly: the family sharing flow itself is covered by 055.
insert into gina.contribution_sets(id,family_id,actor_id,snapshot,fingerprint,status,consent_version) values('70000000-0000-4000-8000-000000009101','10000000-0000-4000-8000-000000009102','00000000-0000-4000-8000-000000009102',
 '{"title":"Çevre sorusu","body":"","grade":5,"subject":"Matematik","grouped":false,"images":[{"id":"80000000-0000-4000-8000-000000009101","sha256":"890c8dc04fe5952ec0d0af6efac019b10bb3287d116b22adcca2e1bd5effdeb8"}],"questions":[{"key":"q1","kind":"open_ended","stem":"Dikdörtgenin çevresi kaç metredir?","choices":[],"topic":"Çevre","grade":5,"subject":"Matematik","difficulty":"orta","correct_key":null}]}'::jsonb,'fingerprint-9101','pending','contribution-v1');
create function pg_temp.bundle() returns jsonb language sql as $$select $fixture${"schema":"gina.library-import.v1","package_key":"test-library-intake","revision":1,"previous_hash":null,"title":"Test import package","grade":5,"subject":"Matematik","provenance":{"locale":"tr","curriculum_reference":{"programme_url":"https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/448?kod=MAB3","programme_page_updated":"2026-09-04","checked_on":"2026-11-03","distribution_index":"https://odsgm.meb.gov.tr/www/1donem-konu-soru-dagilim-tablolari-2026-2027/icerik/1724","candidate_scenario_id":"tr-2026-2027-t1-ilkmat2-g5-d6","candidate_source_sha256":"d5429b5962a08adc04acd71ceaae2d517bca507f8b4cf94354bcd55a9670aebf","mapping_status":"proposed_pending_subject_review"},"programme_version":"2026-09-04 web programme; implementation/school applicability pending review","school_track_applicability":"pending_review","assessment_notes":["20 items form a pool, not a 20-question compulsory session or an official school exam.","Questions sharing a source are related observations; do not count them as independent evidence of mastery.","All difficulty labels are estimates; no empirical calibration or official approval.","Schematic drawing/description does not certify compass, ruler or protractor manipulation.","Do not grade drawing neatness, motor control, gender, handwriting style or response speed."],"private_note":"PRIVATE_PROVENANCE_SECRET"},"assets":[{"key":"segments","mime":"image/png","sha256":"890c8dc04fe5952ec0d0af6efac019b10bb3287d116b22adcca2e1bd5effdeb8","width":1,"height":1,"base64":"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGNwcHAAAAGEAMGDX2mUAAAAAElFTkSuQmCC"}],"sources":[{"key":"segments","title":"İki çizim","body":"A ve B arasında iki ucu noktayla gösterilmiş bir çizim; C noktasından başlayıp D üzerinden sağa doğru devam eden, ucunda ok bulunan başka bir çizim var.","alt":"AB çiziminde iki uç nokta var. CD çiziminde başlangıç C; D üzerinden sağa uzanan ok var.","asset_key":"segments","minimum_reading_width":0,"provenance":{"origin":"original_gina_mathematical_diagram","svg_sha256":"a7465f14b876c2ac11a84384c0082f5d16d5fee29cd75b927b8b3c2a1882709b","color_space":"sRGB"}}],"questions":[{"key":"gina-g5-math-geometry-01","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"kolay","stem":"AB ve CD çizimlerinin geometrik adlarını yaz. Uç noktaları ve devam yönleri bakımından aralarındaki farkı açıkla.","choices":[]},"teacher":{"correct_key":null,"expected_answer":"TEACHER_ANSWER_SECRET","solution":"İki uçta nokta bulunan AB sınırlıdır. CD’de başlangıç C ve devamı gösteren bir ok vardır.","explanation":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"AB’yi doğru parçası olarak adlandırır."},{"id":"c2","points":1,"criterion":"CD’yi ışın olarak adlandırır."},{"id":"c3","points":1,"criterion":"AB’nin iki uç noktayla sınırlı olduğunu belirtir."},{"id":"c4","points":1,"criterion":"CD’nin C’den başlayıp D yönünde devam ettiğini belirtir."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"Ok ucunu ikinci uç nokta sanmak.","next_step":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.2","mapping_status":"proposed_pending_subject_review","evidence_scope":"reasoning"},"response":{"mode":"text_or_drawing","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Metin veya anlamı açık etiketli çizim kabul edilir; yazı güzelliği puanlanmaz."},"evidence_unit":"segments","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical","private_note":"PRIVATE_METADATA_SECRET"}},{"key":"gina-g5-math-geometry-02","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"orta","stem":"Defterinde E ve F adlı iki farklı nokta göster. E’den başlayıp F yönünde devam eden bir ışını şematik çiz veya nasıl çizileceğini tarif et. Düz çizgiyi oluşturmak için hangi aracı seçerdin? Neden?","choices":[]},"teacher":{"correct_key":null,"expected_answer":"E başlangıçtır; çizgi F’den geçer ve F yönünde bir okla devam eder. Düz çizgi için cetvel/çizgeç veya dijital ışın aracı seçilir.","solution":"E ve F işaretlenir. Cetvel iki noktaya hizalanır. E’den başlayıp F’den geçen çizgi F yönüne uzatılır; devam yönü okla gösterilir.","explanation":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"E başlangıç noktasını doğru belirler."},{"id":"c2","points":1,"criterion":"Çizgi veya tarif F’den geçer."},{"id":"c3","points":1,"criterion":"Devam yönünü F yönündeki okla veya eşdeğer sözle gösterir."},{"id":"c4","points":1,"criterion":"Cetvel/çizgeç/dijital ışın aracını düz çizgi oluşturma gerekçesiyle seçer."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"E’nin gerisine de ok ekleyerek ışını doğruya çevirmek.","next_step":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.1","mapping_status":"proposed_pending_subject_review","evidence_scope":"tool_selection_and_schematic_representation_not_instrument_performance"},"response":{"mode":"drawing_or_description","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Kalem zorunlu değildir. Çizim istenen soruda şeklin uçlarını, ok yönünü ve bağlantılarını yazıyla açıkça tarif etmek de kabul edilir. Bu alternatif gerçek araç kullanma becerisi kanıtı sayılmaz."},"evidence_unit":"question-02","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical"}}]}$fixture$::jsonb$$;
create function pg_temp.curriculum() returns jsonb language sql as $$select '
{"schema": "gina.curriculum-review.v1", "candidates": [{"key": "tr-2026-2027-t1-turkce2-g5-c6", "academic_year": "2026-2027", "term": 1, "exam": 1, "grade": 5, "subject": "Türkçe", "source_url": "https://cdn.eba.gov.tr/yardimcikaynaklar/2026/09/KSDT/turkce2.xlsx", "source_sha256": "6405d02aaaadaa4d25a3ce54954dd256a045da9f35d49ee806a3b29565a82cee", "sheet": "5. Sınıf", "header_cell": "C6", "question_count": 6, "blocks": [{"count": 2, "count_cell": "C12", "outcomes": [{"cell": "B12", "text": "T.O.5.6. Metnin yüzey anlamını belirleyebilme", "code": "T.O.5.6"}]}, {"count": 1, "count_cell": "C13", "outcomes": [{"cell": "B13", "text": "T.O.5.7. Görselle iletilen anlamı belirleyebilme", "code": "T.O.5.7"}]}, {"count": 1, "count_cell": "C21", "outcomes": [{"cell": "B21", "text": "T.O.5.20. Metinden hareketle söz varlığını geliştirmeye yönelik çözümleme yapabilme", "code": "T.O.5.20"}]}, {"count": 1, "count_cell": "C30", "outcomes": [{"cell": "B30", "text": "T.Y.5.13. Yazısını zenginleştirecek biçimde söz varlığını kullanabilme", "code": "T.Y.5.13"}]}, {"count": 1, "count_cell": "C32", "outcomes": [{"cell": "B32", "text": "T.Y.5.16. Yazım ve noktalama işaretleriyle ilgili kuralları uygulayabilme", "code": "T.Y.5.16"}]}], "label": "Senaryo 1", "review_reasons": ["programme_and_school_scope_required", "source_review_required"]}]}
'::jsonb$$;
create temp table ids(name text primary key,id uuid); grant all on ids to authenticated,service_role;
create function pg_temp.id(n text) returns uuid language sql as $$select id from ids where name=n$$;
create function pg_temp.q(stmt text) returns text language plpgsql security definer as $$declare v text;begin execute stmt into v;return v;end$$;
grant execute on function pg_temp.q(text) to authenticated,service_role;
create function pg_temp.lease(n int) returns uuid language sql as $$select ('90000000-0000-4000-8000-00000000910'||n)::uuid$$;
create function pg_temp.verdict(conf numeric,reason text default 'all_checks_passed') returns jsonb language sql as $$select jsonb_build_object('model','synthetic-model','confidence',conf,'decision_reason',reason,'findings','[]'::jsonb,'rubric',jsonb_build_object('solution_correct','yes'))$$;

-- Authority -------------------------------------------------------------------------------
set local role anon;
select throws_ok($$select public.enqueue_content_prereview('all')$$,'42501',null,'anonymous cannot enqueue');
select throws_ok($$select public.content_prereview_next()$$,'42501',null,'anonymous cannot read queue');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009102","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000009102"}}',true);
select throws_ok($$select public.enqueue_content_prereview('all')$$,'42501','forbidden','parent cannot enqueue');
select throws_ok($$select public.request_content_prereview('curriculum_candidate',gen_random_uuid())$$,'42501','forbidden','parent cannot request');
select throws_ok($$select public.admin_content_prereviews()$$,'42501','forbidden','parent cannot read verdicts');
select throws_ok($$select public.content_prereview_claim('curriculum_candidate',gen_random_uuid(),gen_random_uuid(),'v1')$$,'42501',null,'parent cannot claim as service');
select throws_ok($$select public.content_prereview_finish('curriculum_candidate',gen_random_uuid(),gen_random_uuid(),'ai_approved','{}')$$,'42501',null,'parent cannot finish as service');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009101","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000009101","admin":true}}',true);
select throws_ok($$select public.content_prereview_claim('curriculum_candidate',gen_random_uuid(),gen_random_uuid(),'v1')$$,'42501',null,'admin JWT cannot use the service claim');
insert into ids select 'package',(public.admin_import_library_bundle('60000000-0000-4000-8000-000000009101',pg_temp.bundle()||'{"package_key":"test-prereview"}')->>'id')::uuid;
select set_config('test.import',public.admin_import_curriculum_candidates('60000000-0000-4000-8000-000000009102',pg_temp.curriculum())::text,true);
insert into ids select 'candidate',pg_temp.q($$select id from gina.curriculum_candidates where external_key='tr-2026-2027-t1-turkce2-g5-c6'$$)::uuid;
insert into ids values('contribution','70000000-0000-4000-8000-000000009101');
select throws_ok($$select public.enqueue_content_prereview('everything')$$,'P0001','prereview_scope_invalid','unknown scope rejected');
select throws_ok($$select public.request_content_prereview('question',gen_random_uuid())$$,'P0001','prereview_kind_invalid','unknown kind rejected');
select throws_ok($$select public.request_content_prereview('library_package',gen_random_uuid())$$,'P0001','prereview_not_found','unknown record rejected');

-- Queue is idempotent --------------------------------------------------------------------
select is(public.enqueue_content_prereview('all')-'scope','{"queued":3,"requeued":0,"unchanged":0}'::jsonb,'bulk run queues the three awaiting records');
select is(public.enqueue_content_prereview('all')-'scope','{"queued":0,"requeued":0,"unchanged":3}'::jsonb,'second bulk run queues nothing');
select is(public.request_content_prereview('curriculum_candidate',pg_temp.id('candidate'))->>'outcome','unchanged','single request on queued record is a no-op');
select is(pg_temp.q($$select count(*) from public.audit_log where action='content_prereview.enqueue'$$)::int,2,'bulk runs audited');
select is(jsonb_array_length(public.admin_content_prereviews('pending')),3,'admin sees the pending queue');
select is(jsonb_array_length(public.admin_content_prereviews('ai_approved')),0,'no verdict before the model ran');
select is((public.admin_content_prereviews()->0) ? 'lease',false,'lease is not exposed to the admin list');

-- Service claim / finish ------------------------------------------------------------------
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(1),'prereview-v1')->>'error','prereview_disabled','feature gate closed by default');
reset role;update public.app_settings set value='true' where key='content_prereview.enabled';set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.content_prereview_claim('curriculum_candidate',gen_random_uuid(),pg_temp.lease(1),'prereview-v1')->>'error','not_found','unknown record is not claimable');
create temp table claimed(result jsonb); grant all on claimed to service_role,authenticated;
insert into claimed select public.content_prereview_claim('library_package',pg_temp.id('package'),pg_temp.lease(1),'prereview-v1');
select is((select result->>'claimed' from claimed),'true','library package claimed');
select is((select (result->>'attempts')::int from claimed),1,'first attempt counted');
select is((select result->'content'->'questions'->0->'teacher'->>'expected_answer' from claimed),'TEACHER_ANSWER_SECRET','model receives the full teacher answer, not only a reference');
select is((select result->'content'->'sources'->0->>'body' from claimed),'A ve B arasında iki ucu noktayla gösterilmiş bir çizim; C noktasından başlayıp D üzerinden sağa doğru devam eden, ucunda ok bulunan başka bir çizim var.','shared source text is normalized into the prompt');
select ok((select position('PRIVATE_PROVENANCE_SECRET' in result::text)=0 and position('PRIVATE_METADATA_SECRET' in result::text)=0 from claimed),'private provenance and metadata notes never reach the model');
select ok((select position('base64' in result::text)=0 from claimed),'image bytes are not sent');
select is(public.content_prereview_claim('library_package',pg_temp.id('package'),pg_temp.lease(2),'prereview-v1')->>'error','in_progress','second lease waits while the first is in flight');
select throws_ok($$select public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(2),'ai_approved',pg_temp.verdict(0.95))$$,'P0001','lease_lost','wrong lease cannot record a verdict');
select throws_ok($$select public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(1),'approved',pg_temp.verdict(0.95))$$,'P0001','prereview_status_invalid','unknown status rejected');
select throws_ok($$select public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(1),'ai_approved','{"model":"x"}')$$,'P0001','prereview_verdict_invalid','verdict without confidence/findings/reason rejected');
select is(public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(1),'ai_approved',pg_temp.verdict(0.95))->>'prereview_status','ai_approved','verdict recorded under the lease');
select throws_ok($$select public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(1),'ai_approved',pg_temp.verdict(0.95))$$,'P0001','lease_lost','finish is not replayable after the lease closed');
select is(public.content_prereview_claim('library_package',pg_temp.id('package'),pg_temp.lease(3),'prereview-v1')->>'cached','true','same content and prompt version is served from the record, no new model call');
select is(public.content_prereview_claim('library_package',pg_temp.id('package'),pg_temp.lease(3),'prereview-v1')->'prereview_verdict'->>'content_hash',(select result->>'content_hash' from claimed),'verdict carries the content hash it judged');
select is(public.content_prereview_claim('library_package',pg_temp.id('package'),pg_temp.lease(4),'prereview-v2')->>'claimed','true','new prompt version re-runs the review');
select is(pg_temp.q($$select attempts from gina.content_prereviews where target_kind='library_package'$$)::int,1,'prompt change resets the attempt counter');
select is(public.content_prereview_finish('library_package',pg_temp.id('package'),pg_temp.lease(4),'ai_approved',pg_temp.verdict(0.9))->>'prereview_status','ai_approved','second version recorded');

-- ai_approved is not a publication and not an admin decision ----------------------------------
select is(pg_temp.q(format($$select count(*) from gina.library_publications where package_id=%L$$,pg_temp.id('package')))::int,0,'ai_approved creates no library publication');
select is(pg_temp.q(format($$select count(*) from gina.library_editorial_reviews where package_id=%L$$,pg_temp.id('package')))::int,0,'ai_approved writes no editorial review');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009101","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000009101","admin":true}}',true);
select is(public.admin_library_publication(pg_temp.id('package'))->'checks'->>'suitable_count','0','publication checks still count zero suitable questions');
select throws_ok(format($$select public.admin_set_library_publication(gen_random_uuid(),%L,0,%L,'Test','Test description',array['plus']::public.plan_code[],'Test label',true,'published')$$,pg_temp.id('package'),public.admin_library_publication(pg_temp.id('package'))->'checks'->>'review_fingerprint'),'P0001','library_publication_review_required','publishing still requires the editorial review after ai_approved');
select is(jsonb_array_length(public.admin_content_prereviews('ai_approved')),1,'admin list shows the AI verdict');
select is((public.admin_content_prereviews('ai_approved')->0->>'awaiting_admin')::boolean,true,'record still awaits the admin decision');

-- needs_admin notifies the admin queue through the outbox, once per content ------------------------
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(5),'prereview-v1')->'content'->'candidate'->'blocks'->0->'outcomes'->0->>'text','T.O.5.6. Metnin yüzey anlamını belirleyebilme','scenario outcome texts are given in full, not as a URL');
select is(public.content_prereview_finish('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(5),'needs_admin',pg_temp.verdict(0.6,'low_confidence'))->>'notified','1','admin who is a family member is notified once');
select is(pg_temp.q(format($$select count(*) from public.push_outbox where kind='content_prereview_needs_admin' and target_user_id='00000000-0000-4000-8000-000000009101' and payload->>'target_id'=%L$$,pg_temp.id('candidate')::text))::int,1,'outbox row targets the admin only');
select is(pg_temp.q($$select count(*) from public.push_outbox where kind='content_prereview_needs_admin' and target_user_id='00000000-0000-4000-8000-000000009103'$$)::int,0,'admin without a family has no push target');
select is(pg_temp.q($$select count(*) from public.push_outbox where kind='content_prereview_needs_admin' and target_user_id='00000000-0000-4000-8000-000000009102'$$)::int,0,'plain parent is not notified');
select is(pg_temp.q($$select count(*) from public.push_targets((select id from public.push_outbox where kind='content_prereview_needs_admin' limit 1))$$)::int,0,'no session yet: outbox row has no target until the admin signs in');
select is(pg_temp.q(format($$select status from gina.curriculum_candidates where id=%L$$,pg_temp.id('candidate'))),'draft','needs_admin leaves the candidate status untouched');
select is(pg_temp.q(format($$select review::text from gina.curriculum_candidates where id=%L$$,pg_temp.id('candidate'))),null,'needs_admin writes no admin review');
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(6),'prereview-v1')->>'cached','true','needs_admin verdict is cached too');
-- Contribution: explicit reject suggestion, still no automatic rejection.
select is(public.content_prereview_claim('contribution_set',pg_temp.id('contribution'),pg_temp.lease(7),'prereview-v1')->'content'->'snapshot'->'questions'->0->>'stem','Dikdörtgenin çevresi kaç metredir?','contribution snapshot is normalized');
select ok((public.content_prereview_claim('contribution_set',pg_temp.id('contribution'),pg_temp.lease(7),'prereview-v1')->>'error')='in_progress','contribution claim held by first lease');
select is(public.content_prereview_finish('contribution_set',pg_temp.id('contribution'),pg_temp.lease(7),'ai_rejected_suggestion',pg_temp.verdict(0.92,'blocking_finding')||'{"findings":[{"code":"leaked_exam_suspicion","severity":"blocking","detail":"synthetic"}]}')->>'prereview_status','ai_rejected_suggestion','reject suggestion recorded');
select is(pg_temp.q(format($$select status from gina.contribution_sets where id=%L$$,pg_temp.id('contribution'))),'pending','reject suggestion does not reject the contribution');
select is(pg_temp.q(format($$select reviewed_by::text from gina.contribution_sets where id=%L$$,pg_temp.id('contribution'))),null,'no admin decision is forged');
select is(pg_temp.q($$select count(*) from public.push_outbox where kind='content_prereview_needs_admin'$$)::int,2,'reject suggestion also lands in the admin queue');
select is(pg_temp.q('select count(*) from gina.content_prereview_notices')::int,2,'one notice per content');

-- Changed content re-queues; admin decision stays separate ------------------------------------------
reset role;
update gina.curriculum_candidates set candidate=candidate||'{"label":"Senaryo 1 (revize)"}' where id=pg_temp.id('candidate');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(8),'prereview-v1')->>'claimed','true','changed content is reviewed again');
select is(pg_temp.q($$select prereview_verdict::text from gina.content_prereviews where target_kind='curriculum_candidate'$$),null,'old verdict is not carried onto new content');
select is(public.content_prereview_finish('curriculum_candidate',pg_temp.id('candidate'),pg_temp.lease(8),'needs_admin',pg_temp.verdict(0.5,'low_confidence'))->>'notified','1','new content notifies again');
select is(pg_temp.q('select count(*) from gina.content_prereview_notices')::int,3,'notice keyed by content hash');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009101","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000009101","admin":true}}',true);
select is(public.enqueue_content_prereview('curriculum_candidates')-'scope','{"queued":0,"requeued":0,"unchanged":1}'::jsonb,'bulk run keeps a fresh verdict');
select lives_ok(format($$select public.admin_change_curriculum_candidate(gen_random_uuid(),%L,%s,'review','%s'::jsonb,'Human review for test',true)$$,pg_temp.id('candidate'),pg_temp.q(format($$select revision from gina.curriculum_candidates where id=%L$$,pg_temp.id('candidate'))),'{"programme":"Test programme version","school_scope":"Synthetic scope for testing only","programme_url":"https://tymm.meb.gov.tr/ogretim-programlari","source_checked":true,"counts_checked":true,"applicability_checked":true,"issues_resolution":"Synthetic evidence reviewed for test only.","note":"Test source review, not real catalogue approval."}'),'admin decides independently of the AI verdict');
select is(pg_temp.q($$select prereview_status from gina.content_prereviews where target_kind='curriculum_candidate'$$),'needs_admin','admin decision does not rewrite the AI record');
select is(pg_temp.q(format($$select status from gina.curriculum_candidates where id=%L$$,pg_temp.id('candidate'))),'reviewed','admin decision lives in the candidate columns');
select is((public.admin_content_prereviews()->0->>'awaiting_admin')::boolean,false,'queue view reflects that the admin has decided');
select is(public.enqueue_content_prereview('curriculum_candidates')-'scope','{"queued":0,"requeued":0,"unchanged":0}'::jsonb,'reviewed candidate leaves the bulk scope');

-- Retry limit -----------------------------------------------------------------------------
reset role;
insert into gina.curriculum_candidates(external_key,source_sha256,candidate,content_hash,status,created_by) values('retry-limit-9101','6405d02aaaadaa4d25a3ce54954dd256a045da9f35d49ee806a3b29565a82cee','{"label":"retry"}','6405d02aaaadaa4d25a3ce54954dd256a045da9f35d49ee806a3b29565a82cee','draft','00000000-0000-4000-8000-000000009101');
insert into ids select 'retry',id from gina.curriculum_candidates where external_key='retry-limit-9101';
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(1),'prereview-v1')->>'claimed','true','retry attempt 1');
select is(public.content_prereview_finish('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(1),'pending',null,'anthropic_529')->>'prereview_status','pending','provider failure keeps the record pending');
select is(pg_temp.q(format($$select last_error from gina.content_prereviews where target_id=%L$$,pg_temp.id('retry'))),'anthropic_529','failure reason recorded');
select is(public.content_prereview_next(10),jsonb_build_array(jsonb_build_object('kind','curriculum_candidate','id',pg_temp.id('retry'))),'worker sees only the pending retryable record');
select is((public.content_prereview_claim('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(2),'prereview-v1')->>'attempts')::int,2,'retry attempt 2');
select lives_ok($$select public.content_prereview_finish('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(2),'pending',null,'ai_result_invalid')$$,'malformed output is a retryable failure');
select is((public.content_prereview_claim('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(3),'prereview-v1')->>'attempts')::int,3,'retry attempt 3');
select lives_ok($$select public.content_prereview_finish('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(3),'pending',null,'anthropic_timeout')$$,'third failure recorded');
-- H07: the exhausted record stays visible to the worker so the next claim retires it for free (it used to stick).
select is(public.content_prereview_next(10),jsonb_build_array(jsonb_build_object('kind','curriculum_candidate','id',pg_temp.id('retry'))),'exhausted record stays visible so the next claim retires it (H07)');
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(4),'prereview-v1')->>'error','retry_limit','fourth claim trips the retry limit');
select is(pg_temp.q(format($$select prereview_status from gina.content_prereviews where target_id=%L$$,pg_temp.id('retry'))),'needs_admin','retry limit routes to the admin');
select is(pg_temp.q(format($$select prereview_verdict->>'decision_reason' from gina.content_prereviews where target_id=%L$$,pg_temp.id('retry'))),'retry_limit','reason is recorded');
select is(pg_temp.q(format($$select count(*) from public.push_outbox where kind='content_prereview_needs_admin' and payload->>'target_id'=%L$$,pg_temp.id('retry')::text))::int,1,'retry limit notifies the admin once');
select is(public.content_prereview_claim('curriculum_candidate',pg_temp.id('retry'),pg_temp.lease(5),'prereview-v1')->>'cached','true','exhausted record is cached as needs_admin');
select is(pg_temp.q($$select count(*) from public.audit_log where action like 'content_prereview.%'$$)::int,10,'every verdict, enqueue and retry limit is audited');
select * from finish();
rollback;
